 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seeds = {grid[0][c]: c for c in range(w) if grid[0][c] != 0}

    # Each color in the top marker extends down its column until its matching
    # horizontal marker (if present), or to the bottom edge otherwise.
    for color, col in seeds.items():
        marker_rows = [r for r in range(1, h) if color in grid[r]]
        stop = min(marker_rows) if marker_rows else h - 1
        for r in range(1, stop + 1):
            out[r][col] = color

    # Off-axis matching markers extend horizontally to the top marker column.
    for r in range(1, h):
        for c in range(w):
            color = grid[r][c]
            if color in seeds:
                seed_col = seeds[color]
                for x in range(min(c, seed_col), max(c, seed_col) + 1):
                    out[r][x] = color
    return out

if __name__ == '__main__':
